import{_ as s,C as l,o as a,c as i,a2 as o,b as n,w as r,a as E,E as A,a3 as d}from"./chunks/framework.BBdhqAg0.js";const C="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",b=JSON.parse('{"title":"권한 설정 관리","description":"","frontmatter":{},"headers":[],"relativePath":"authority/manage.md","filePath":"authority/manage.md","lastUpdated":1793195756000}'),c={name:"authority/manage.md"};function g(B,e,u,m,_,p){const t=l("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="권한-설정-관리" tabindex="-1">권한 설정 관리 <a class="header-anchor" href="#권한-설정-관리" aria-label="Permalink to &quot;권한 설정 관리&quot;">​</a></h1><p>시스템을 이용하는 사용자별로 프로젝트 접근 권한을 관리하고, 각 부동산 개발 프로젝트별 비즈니스 데이터 처리 역할(Role)을 지정하는 관리자 전용 화면입니다.</p><ul><li><strong>위치</strong>: <code>환경설정 &gt; 권한 설정 관리</code></li></ul><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+C+'" alt="권한 설정 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/manage.png</code> 경로에 등록해 주세요.</em></p></div><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>회사의 조직 구조와 프로젝트 담당 업무에 맞춰 사용자별 비즈니스 권한을 체계적으로 통제합니다. 사용자를 선택한 후, 각 부동산 개발 프로젝트별로 부여할 프로젝트 비즈니스 역할(<code>ibs_pr_manage</code> 카테고리 역할)을 체크박스로 손쉽게 할당하거나 해제할 수 있으며, 신규 직원에 대한 계정 생성 및 보안 초기 접속 메일 발송을 지원합니다.</p>',6)),(a(),n(d,null,{default:r(()=>[A(t,{id:"mermaid-24",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%EB%8C%80%EC%83%81%20%EC%82%AC%EC%9A%A9%EC%9E%90%20%EC%84%A0%ED%83%9D%3Cbr%2F%3E(%EC%A0%84%EC%B2%B4%20%EC%82%AC%EC%9A%A9%EC%9E%90%20%EA%B2%80%EC%83%89)%22%5D%20--%3E%20B%5B%222.%20%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%EC%B9%B4%EB%93%9C%20%ED%99%95%EC%9D%B8%3Cbr%2F%3E(%EC%9A%B4%EC%98%81%20%EC%A4%91%EC%9D%B8%20%EB%B6%80%EB%8F%99%EC%82%B0%20%EA%B0%9C%EB%B0%9C%20%EC%82%AC%EC%97%85%EC%A7%80)%22%5D%0A%20%20%20%20C%5B%22%EC%8B%A0%EA%B7%9C%20%EC%82%AC%EC%9A%A9%EC%9E%90%20%EC%83%9D%EC%84%B1%3Cbr%2F%3E(%EC%9E%84%EC%9D%98%20%ED%8C%A8%EC%8A%A4%EC%9B%8C%EB%93%9C%C2%B7%EC%B4%88%EB%8C%80%20%EB%A9%94%EC%9D%BC)%22%5D%20-.-%3E%20A%0A%20%20%20%20B%20--%3E%20D%5B%223.%20%EB%B9%84%EC%A6%88%EB%8B%88%EC%8A%A4%20%EC%97%AD%ED%95%A0%20%EC%A7%80%EC%A0%95%3Cbr%2F%3E(ibs_pr_manage%20%EC%B2%B4%ED%81%AC%20%ED%86%A0%EA%B8%80)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%224.%20%EB%A9%A4%EB%B2%84%EC%8B%AD%20%EC%9E%90%EB%8F%99%20%EC%97%B0%EB%8F%99%3Cbr%2F%3E(%ED%96%89%20%EB%8B%A8%EC%9C%84%20RLS%20%EA%B6%8C%ED%95%9C%20%EC%A6%89%EC%8B%9C%20%EC%A0%81%EC%9A%A9)%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ul><li><strong>사용자 선택 및 권한 조회</strong>: 등록된 전체 사용자 중 대상을 선택하여 개별 프로젝트별로 부여된 비즈니스 역할 현황을 실시간 확인</li><li><strong>신규 사용자 즉시 생성</strong>: 업무 관리자(<code>workManager</code>) 권한을 가진 관리자는 [사용자 생성] 버튼을 통해 새 계정을 시스템에 직접 등록</li><li><strong>암호학적 임의 패스워드 생성</strong>: 사용자 생성 시 보안 규칙을 만족하는 8자리 임시 비밀번호 자동 생성</li><li><strong>보안 초대 메일 발송</strong>: 신규 사용자에게 계정 등록 안내 메일을 발송하며, 패스워드 재설정 링크(만료 시간 1~24시간 지정) 또는 임시 비밀번호 포함 옵션 제공</li><li><strong>프로젝트별 비즈니스 역할(<code>ibs_pr_manage</code>) 매핑</strong>: 운영 중인 부동산 개발 프로젝트별로 계약, 수납, 회계 장부, 유닛 관리 등 실무 역할을 체크박스 클릭으로 즉시 할당/회수</li><li><strong>원클릭 프로젝트 멤버십 동기화</strong>: 프로젝트 카드 내 역할을 1개 이상 체크하면 해당 프로젝트의 멤버십이 자동 생성되고, 모든 역할을 해제하면 멤버십에서 자동 제외</li></ul><h2 id="화면-구성-및-실무-가이드" tabindex="-1">화면 구성 및 실무 가이드 <a class="header-anchor" href="#화면-구성-및-실무-가이드" aria-label="Permalink to &quot;화면 구성 및 실무 가이드&quot;">​</a></h2><h3 id="_1-사용자-선택-영역-user-select" tabindex="-1">1. 사용자 선택 영역 (User Select) <a class="header-anchor" href="#_1-사용자-선택-영역-user-select" aria-label="Permalink to &quot;1. 사용자 선택 영역 (User Select)&quot;">​</a></h3><p>권한을 조회하고 변경할 대상 사용자를 지정하는 영역입니다.</p><ul><li><strong>사용자 선택 드롭다운</strong>: 시스템에 등록된 전체 사용자 중 권한을 설정할 임직원을 검색하여 선택합니다.</li><li><strong>[사용자 생성] 버튼</strong>: 업무 관리자(<code>workManager</code>) 권한자에게만 상단 우측에 노출되며, 신규 계정 등록 모달을 호출합니다.</li></ul><h3 id="_2-신규-사용자-생성-모달-add-user-modal" tabindex="-1">2. 신규 사용자 생성 모달 (Add User Modal) <a class="header-anchor" href="#_2-신규-사용자-생성-모달-add-user-modal" aria-label="Permalink to &quot;2. 신규 사용자 생성 모달 (Add User Modal)&quot;">​</a></h3><p>새로운 직원을 시스템에 등록하고 초기 접속 안내를 진행합니다.</p><ol><li><strong>기본 계정 정보 입력</strong>: 로그인 아이디(영문/숫자), 공식 업무 이메일, 초기 비밀번호를 입력합니다.</li><li><strong>임의 패스워드 자동 생성</strong>: <code>[임의 패스워드 생성]</code> 버튼을 클릭하면 난수화된 안전한 임시 비밀번호가 자동 생성되며, <code>[적용]</code>을 누르면 비밀번호 입력란에 자동 반영됩니다.</li><li><strong>알림 메일 발송 옵션</strong>: <ul><li><code>패스워드 재설정 링크 포함 (권장)</code>: 링크 유효 시간(1~24시간)을 지정하여 보안 비밀번호 재설정 이메일을 보냅니다. 사용자가 직접 안전하게 비밀번호를 등록할 수 있습니다.</li><li><code>사용자 패스워드 포함</code>: 생성된 임시 비밀번호를 이메일 본문에 직접 기재하여 안내합니다.</li></ul></li></ol><h3 id="_3-프로젝트별-담당-권한-설정-영역-project-business-permissions" tabindex="-1">3. 프로젝트별 담당 권한 설정 영역 (Project Business Permissions) <a class="header-anchor" href="#_3-프로젝트별-담당-권한-설정-영역-project-business-permissions" aria-label="Permalink to &quot;3. 프로젝트별 담당 권한 설정 영역 (Project Business Permissions)&quot;">​</a></h3><p>선택된 사용자의 사업지별 비즈니스 데이터 처리 역할을 지정합니다.</p><ul><li><strong>프로젝트 카드 목록</strong>: 현재 활성화되어 운영 중인 부동산 개발 프로젝트들이 카드 형태로 나열됩니다. <ul><li>비공개로 운영되는 사업지는 카드 우측 상단에 <strong><code>🔒 비공개</code></strong> 배지가 함께 표시됩니다.</li></ul></li><li><strong>비즈니스 역할 (<code>ibs_pr_manage</code>) 체크박스</strong>: <ul><li>카드 내에서 해당 직원이 담당할 업무(예: 분양 계약 관리, 대금 수납 관리, 프로젝트 회계 관리 등) 체크박스를 선택하면, 즉시 해당 프로젝트 멤버십이 생성되고 권한이 활성화됩니다.</li><li>모든 체크박스를 해제하면 해당 프로젝트 멤버십에서 자동으로 탈퇴 처리되어 불필요한 데이터 노출을 원천 방지합니다.</li></ul></li></ul><h2 id="💡-실무-관리-포인트" tabindex="-1">💡 실무 관리 포인트 <a class="header-anchor" href="#💡-실무-관리-포인트" aria-label="Permalink to &quot;💡 실무 관리 포인트&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>프로젝트 기반 행 단위 데이터 보안 (Row-Level Security)</strong> 시스템은 프로젝트 멤버십 및 할당된 비즈니스 역할(<code>Role</code>)을 기준으로 계약자 개인정보, 수납 내역, 지출 장부, 예산 등 핵심 비즈니스 데이터의 조회 및 수정 범위를 데이터베이스 레벨에서 엄격하게 통제합니다.</p></div><ul><li><strong>최소 권한 부여 원칙 (Principle of Least Privilege)</strong>: 데이터 보안 및 개인정보 보호를 위해 임직원에게는 현재 실제로 담당하는 프로젝트와 업무에 꼭 필요한 역할만 최소한으로 부여하는 것을 권장합니다.</li><li><strong>비공개 프로젝트 보안 격리</strong>: <code>🔒 비공개</code> 설정된 프로젝트는 해당 프로젝트 멤버로 명시적으로 등록된 사용자에게만 데이터와 메뉴가 노출됩니다. 멤버가 아닌 일반 직원의 화면에서는 해당 프로젝트의 존재 자체가 은폐됩니다.</li><li><strong>보안 초대 메일 링크 활용</strong>: 신규 계정 발급 시 임시 비밀번호를 평문으로 메일에 적어 보내는 것보다, <strong>[패스워드 재설정 링크 포함]</strong> 방식을 사용하는 것이 정보 보안상 가장 안전합니다.</li></ul>',15))])}const D=s(c,[["render",g]]);export{b as __pageData,D as default};
